code='''from collections import Counter, deque

def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            out.append(cells)
    return out

def transform(grid):
    g = [row[:] for row in grid]
    counts = Counter(x for row in g for x in row)
    background = counts.most_common(1)[0][0]
    # The marker is the largest non-background color represented by one object.
    choices = []
    for color in counts:
        if color == background:
            continue
        cs = components(g, color)
        if len(cs) == 1:
            cells = cs[0]
            choices.append((len(cells), color, cells))
    if not choices:
        return g
    _, marker, mcells = max(choices)
    mr0 = min(r for r,c in mcells)
    mc0, mc1 = min(c for r,c in mcells), max(c for r,c in mcells)
    # Recolor the nearest object above the marker whose horizontal extent overlaps it.
    candidates = []
    for color in counts:
        if color in (background, marker):
            continue
        for cells in components(g, color):
            r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
            c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
            if r1 < mr0 and c0 <= mc1 and c1 >= mc0:
                candidates.append((mr0-r1, -len(cells), color, cells))
    if candidates:
        _, _, _, cells = min(candidates)
        for r,c in cells:
            g[r][c] = marker
    return g
'''
